CREATE TABLE IF NOT EXISTS "migrations" ("id" integer not null primary key autoincrement, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer not null primary key autoincrement, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "image" text not null, "role" text, "permission" text, "a_type" varchar, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "dashboard_preferences" text);
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE TABLE IF NOT EXISTS "password_resets" ("email" varchar not null, "token" varchar not null, "created_at" datetime);
CREATE INDEX "password_resets_email_index" on "password_resets" ("email");
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer not null primary key autoincrement, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime default CURRENT_TIMESTAMP not null);
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE TABLE IF NOT EXISTS "personal_access_tokens" ("id" integer not null primary key autoincrement, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" varchar not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE INDEX "personal_access_tokens_tokenable_type_tokenable_id_index" on "personal_access_tokens" ("tokenable_type", "tokenable_id");
CREATE UNIQUE INDEX "personal_access_tokens_token_unique" on "personal_access_tokens" ("token");
CREATE TABLE IF NOT EXISTS "courses" ("id" integer not null primary key autoincrement, "name" varchar not null, "slug" varchar not null, "duration" varchar not null, "semester" varchar not null, "requirement" varchar not null, "starting_time" varchar not null, "closing_time" varchar not null, "image" text not null, "gallery" text not null, "status" integer, "description" text not null, "fulldescription" text not null, "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "courses_slug_unique" on "courses" ("slug");
CREATE TABLE IF NOT EXISTS "testimonials" ("id" integer not null primary key autoincrement, "name" varchar not null, "role" varchar not null, "image" text not null, "description" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "teachers" ("id" integer not null primary key autoincrement, "name" varchar not null, "role" varchar not null, "facebook_link" varchar, "image" text not null, "created_at" datetime, "updated_at" datetime, "staff_type" varchar not null default 'teaching');
CREATE TABLE IF NOT EXISTS "galleries" ("id" integer not null primary key autoincrement, "gallery" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "events" ("id" integer not null primary key autoincrement, "name" varchar not null, "slug" varchar not null, "status" integer, "visit_date" date not null, "image" text not null, "description" text not null, "created_at" datetime, "updated_at" datetime, "event_type" varchar not null default 'event', "venue" varchar, "result_link" varchar, "gallery" text);
CREATE UNIQUE INDEX "events_slug_unique" on "events" ("slug");
CREATE TABLE IF NOT EXISTS "counters" ("id" integer not null primary key autoincrement, "title1" varchar not null, "counter1" varchar not null, "title2" varchar not null, "counter2" varchar not null, "title3" varchar not null, "counter3" varchar not null, "title4" varchar not null, "counter4" varchar not null, "created_at" datetime, "updated_at" datetime, "section_tag" varchar not null default 'Our Impact', "section_title" varchar not null default 'Numbers That Reflect Our Growth', "section_description" varchar, "suffix1" varchar not null default '+', "icon1" varchar not null default 'fa-solid fa-users', "suffix2" varchar not null default '+', "icon2" varchar not null default 'fa-solid fa-graduation-cap', "suffix3" varchar not null default '+', "icon3" varchar not null default 'fa-solid fa-trophy', "suffix4" varchar not null default '+', "icon4" varchar not null default 'fa-solid fa-book');
CREATE TABLE IF NOT EXISTS "tokens" ("id" integer not null primary key autoincrement, "email" varchar not null, "code" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "about_us" ("id" integer not null primary key autoincrement, "desc" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "privacypolicies" ("id" integer not null primary key autoincrement, "desc" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "notices" ("id" integer not null primary key autoincrement, "title" varchar not null, "slug" varchar not null, "image" text not null, "description" text not null, "show_in" varchar not null, "created_at" datetime, "updated_at" datetime, "target_roles" text, "target_classes" text, "target_sections" text, "target_users" text, "status" varchar not null default 'draft', "published_at" datetime, "is_school" tinyint(1) not null default '0');
CREATE UNIQUE INDEX "notices_slug_unique" on "notices" ("slug");
CREATE TABLE IF NOT EXISTS "messages" ("id" integer not null primary key autoincrement, "name" varchar not null, "email" varchar not null, "phone" varchar not null, "address" varchar not null, "desc" varchar not null, "created_at" datetime, "updated_at" datetime, "is_read" tinyint(1) not null default '0');
CREATE TABLE IF NOT EXISTS "banners" ("id" integer not null primary key autoincrement, "title1" varchar not null, "title2" varchar not null, "image" text not null, "status" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "pages" ("id" integer not null primary key autoincrement, "title" varchar not null, "slug" varchar not null, "content" text not null, "status" integer not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "pages_slug_unique" on "pages" ("slug");
CREATE TABLE IF NOT EXISTS "college_messages" ("id" integer not null primary key autoincrement, "name" varchar not null, "designation" varchar not null, "message" text not null, "image" varchar, "order" integer not null default '0', "status" integer not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "home_sections" ("id" integer not null primary key autoincrement, "key" varchar not null, "label" varchar not null, "is_visible" tinyint(1) not null default '1', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "home_sections_key_unique" on "home_sections" ("key");
CREATE TABLE IF NOT EXISTS "about_us_faqs" ("id" integer not null primary key autoincrement, "question" varchar not null, "answer" text not null, "sort_order" integer not null default '1', "status" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "site_settings" ("id" integer not null primary key autoincrement, "site_name" varchar not null default 'Green Peace Lincoln College', "site_short_name" varchar not null default 'GPLC', "site_tagline" varchar not null default 'Affiliated with Lincoln University Malaysia', "primary_color" varchar not null default '#2d6a4f', "primary_dark" varchar not null default '#1a472a', "primary_light" varchar not null default '#40916c', "accent_color" varchar not null default '#52b788', "contact_phone" varchar, "contact_email" varchar, "contact_address" varchar, "whatsapp_number" varchar, "facebook_url" varchar, "youtube_url" varchar, "instagram_url" varchar, "gallery_layout" varchar not null default 'masonry', "created_at" datetime, "updated_at" datetime, "header_button_text" varchar, "header_button_url" varchar, "student_portal_text" varchar, "student_portal_url" varchar, "show_sticky_notice" tinyint(1) not null default '1', "sticky_notice_title" varchar, "sticky_notice_limit" integer not null default '5', "show_topbar" tinyint(1) not null default '1', "show_whatsapp_button" tinyint(1) not null default '1', "show_back_to_top" tinyint(1) not null default '1', "sticky_notice_desktop_collapsed" tinyint(1) not null default '0', "sticky_notice_mobile_collapsed" tinyint(1) not null default '1', "site_logo" varchar, "site_favicon" varchar, "calendar_system" varchar not null default 'AD', "enable_online_admission" tinyint(1) not null default '0');
CREATE TABLE IF NOT EXISTS "campus_calendar_entries" ("id" integer not null primary key autoincrement, "title" varchar not null, "entry_type" varchar not null default 'other', "start_date" date not null, "end_date" date, "result_link" varchar, "description" text, "status" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "activity_logs" ("id" integer not null primary key autoincrement, "module" varchar not null, "action" varchar not null, "user_name" varchar, "summary" text, "created_at" datetime, "updated_at" datetime, "user_id" integer, "ip_address" varchar, "location" varchar, "user_agent" text, "model_type" varchar, "model_id" integer, "properties" text);
CREATE TABLE IF NOT EXISTS "navbar_items" ("id" integer not null primary key autoincrement, "title" varchar not null, "type" varchar check ("type" in ('route', 'page', 'custom', 'dynamic_courses')) not null default 'custom', "value" varchar, "target" varchar not null default '_self', "parent_id" integer, "order" integer not null default '0', "css_class" varchar, "created_at" datetime, "updated_at" datetime, foreign key("parent_id") references "navbar_items"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "exams" ("id" integer not null primary key autoincrement, "title" varchar not null, "status" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, "academic_year_id" integer, "start_date" date, "end_date" date, "description" text, "is_published" tinyint(1) not null default '0');
CREATE TABLE IF NOT EXISTS "permissions" ("id" integer not null primary key autoincrement, "name" varchar not null, "guard_name" varchar not null, "created_at" datetime, "updated_at" datetime, "module_name" varchar);
CREATE UNIQUE INDEX "permissions_name_guard_name_unique" on "permissions" ("name", "guard_name");
CREATE TABLE IF NOT EXISTS "roles" ("id" integer not null primary key autoincrement, "name" varchar not null, "guard_name" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "roles_name_guard_name_unique" on "roles" ("name", "guard_name");
CREATE TABLE IF NOT EXISTS "model_has_permissions" ("permission_id" integer not null, "model_type" varchar not null, "model_id" integer not null, foreign key("permission_id") references "permissions"("id") on delete cascade, primary key ("permission_id", "model_id", "model_type"));
CREATE INDEX "model_has_permissions_model_id_model_type_index" on "model_has_permissions" ("model_id", "model_type");
CREATE TABLE IF NOT EXISTS "model_has_roles" ("role_id" integer not null, "model_type" varchar not null, "model_id" integer not null, foreign key("role_id") references "roles"("id") on delete cascade, primary key ("role_id", "model_id", "model_type"));
CREATE INDEX "model_has_roles_model_id_model_type_index" on "model_has_roles" ("model_id", "model_type");
CREATE TABLE IF NOT EXISTS "role_has_permissions" ("permission_id" integer not null, "role_id" integer not null, foreign key("permission_id") references "permissions"("id") on delete cascade, foreign key("role_id") references "roles"("id") on delete cascade, primary key ("permission_id", "role_id"));
CREATE TABLE IF NOT EXISTS "academic_years" ("id" integer not null primary key autoincrement, "name" varchar not null, "start_date" date not null, "end_date" date not null, "is_active" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "streams" ("id" integer not null primary key autoincrement, "name" varchar not null, "code" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "academic_classes" ("id" integer not null primary key autoincrement, "name" varchar not null, "numeric_value" integer not null, "stream_id" integer, "created_at" datetime, "updated_at" datetime, foreign key("stream_id") references "streams"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "subjects" ("id" integer not null primary key autoincrement, "name" varchar not null, "code" varchar not null, "type" varchar check ("type" in ('theory', 'practical', 'both')) not null default 'theory', "created_at" datetime, "updated_at" datetime, "order_level" integer not null default '0');
CREATE UNIQUE INDEX "subjects_code_unique" on "subjects" ("code");
CREATE TABLE IF NOT EXISTS "departments" ("id" integer not null primary key autoincrement, "name" varchar not null, "description" text, "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "departments_name_unique" on "departments" ("name");
CREATE TABLE IF NOT EXISTS "designations" ("id" integer not null primary key autoincrement, "name" varchar not null, "description" text, "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "designations_name_unique" on "designations" ("name");
CREATE TABLE IF NOT EXISTS "staff" ("id" integer not null primary key autoincrement, "employee_id" varchar not null, "department_id" integer, "designation_id" integer, "first_name" varchar not null, "last_name" varchar not null, "gender" varchar, "dob" date, "date_of_joining" date, "email" varchar, "phone" varchar, "emergency_contact" varchar, "marital_status" varchar, "photo" varchar, "resume" varchar, "current_address" text, "permanent_address" text, "qualification" text, "experience" text, "basic_salary" numeric, "contract_type" varchar, "status" varchar not null default 'Active', "show_on_website" tinyint(1) not null default '0', "user_id" integer, "created_at" datetime, "updated_at" datetime, "consent_birthday_post" tinyint(1) not null default '1', foreign key("department_id") references "departments"("id") on delete set null, foreign key("designation_id") references "designations"("id") on delete set null, foreign key("user_id") references "users"("id") on delete set null);
CREATE UNIQUE INDEX "staff_employee_id_unique" on "staff" ("employee_id");
CREATE TABLE IF NOT EXISTS "staff_documents" ("id" integer not null primary key autoincrement, "staff_id" integer not null, "title" varchar not null, "document_path" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("staff_id") references "staff"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "guardians" ("id" integer not null primary key autoincrement, "father_name" varchar, "father_phone" varchar, "father_occupation" varchar, "mother_name" varchar, "mother_phone" varchar, "mother_occupation" varchar, "guardian_name" varchar, "guardian_relation" varchar, "guardian_phone" varchar, "guardian_email" varchar, "guardian_address" text, "user_id" integer, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "students" ("id" integer not null primary key autoincrement, "admission_no" varchar not null, "admission_date" date, "first_name" varchar not null, "last_name" varchar, "gender" varchar, "dob" date, "blood_group" varchar, "religion" varchar, "category" varchar, "current_address" text, "permanent_address" text, "photo" varchar, "previous_school_details" text, "guardian_id" integer not null, "status" varchar not null default 'Active', "user_id" integer, "created_at" datetime, "updated_at" datetime, "theme" varchar not null default 'default', "font" varchar not null default 'Inter', "avatar" varchar, "points" integer not null default '0', "consent_birthday_post" tinyint(1) not null default '1', foreign key("guardian_id") references "guardians"("id") on delete cascade);
CREATE UNIQUE INDEX "students_admission_no_unique" on "students" ("admission_no");
CREATE TABLE IF NOT EXISTS "enrollments" ("id" integer not null primary key autoincrement, "student_id" integer not null, "academic_year_id" integer not null, "academic_class_id" integer not null, "section_id" integer, "stream_id" integer, "roll_no" integer, "status" varchar not null default 'Continuing', "created_at" datetime, "updated_at" datetime, foreign key("student_id") references "students"("id") on delete cascade, foreign key("academic_year_id") references "academic_years"("id") on delete cascade, foreign key("academic_class_id") references "academic_classes"("id") on delete cascade, foreign key("section_id") references "sections"("id") on delete set null, foreign key("stream_id") references "streams"("id") on delete set null);
CREATE UNIQUE INDEX "enrollments_student_id_academic_year_id_unique" on "enrollments" ("student_id", "academic_year_id");
CREATE TABLE IF NOT EXISTS "student_documents" ("id" integer not null primary key autoincrement, "student_id" integer not null, "title" varchar not null, "document_path" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("student_id") references "students"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "student_attendances" ("id" integer not null primary key autoincrement, "date" date not null, "academic_year_id" integer not null, "academic_class_id" integer not null, "section_id" integer not null, "student_id" integer not null, "status" varchar check ("status" in ('Present', 'Absent', 'Late', 'Half-Day')) not null default 'Present', "remarks" varchar, "created_at" datetime, "updated_at" datetime, foreign key("academic_year_id") references "academic_years"("id") on delete cascade, foreign key("academic_class_id") references "academic_classes"("id") on delete cascade, foreign key("section_id") references "sections"("id") on delete cascade, foreign key("student_id") references "students"("id") on delete cascade);
CREATE UNIQUE INDEX "student_attendances_student_id_date_unique" on "student_attendances" ("student_id", "date");
CREATE TABLE IF NOT EXISTS "staff_attendances" ("id" integer not null primary key autoincrement, "staff_id" integer not null, "date" date not null, "status" varchar check ("status" in ('Present', 'Absent', 'Late', 'Half-Day')) not null default 'Present', "remarks" varchar, "created_at" datetime, "updated_at" datetime, foreign key("staff_id") references "staff"("id") on delete cascade);
CREATE UNIQUE INDEX "staff_attendances_staff_id_date_unique" on "staff_attendances" ("staff_id", "date");
CREATE TABLE IF NOT EXISTS "leave_requests" ("id" integer not null primary key autoincrement, "leavable_type" varchar not null, "leavable_id" integer not null, "start_date" date not null, "end_date" date not null, "reason" text not null, "status" varchar check ("status" in ('Pending', 'Approved', 'Rejected')) not null default 'Pending', "remarks" text, "created_at" datetime, "updated_at" datetime);
CREATE INDEX "leave_requests_leavable_type_leavable_id_index" on "leave_requests" ("leavable_type", "leavable_id");
CREATE TABLE IF NOT EXISTS "class_subject_assignments" ("id" integer not null primary key autoincrement, "academic_year_id" integer not null, "academic_class_id" integer not null, "section_id" integer, "subject_id" integer not null, "staff_id" integer, "weekly_periods" integer, "created_at" datetime, "updated_at" datetime, foreign key("academic_year_id") references "academic_years"("id") on delete cascade, foreign key("academic_class_id") references "academic_classes"("id") on delete cascade, foreign key("section_id") references "sections"("id") on delete set null, foreign key("subject_id") references "subjects"("id") on delete cascade, foreign key("staff_id") references "staff"("id") on delete set null);
CREATE UNIQUE INDEX "unique_class_subject" on "class_subject_assignments" ("academic_year_id", "academic_class_id", "section_id", "subject_id");
CREATE TABLE IF NOT EXISTS "admission_enquiries" ("id" integer not null primary key autoincrement, "name" varchar not null, "phone" varchar not null, "email" varchar, "academic_class_id" integer, "source" varchar, "status" varchar not null default 'Open', "notes" text, "enquiry_date" date not null, "created_at" datetime, "updated_at" datetime, foreign key("academic_class_id") references "academic_classes"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "admission_applications" ("id" integer not null primary key autoincrement, "first_name" varchar not null, "last_name" varchar not null, "dob" date not null, "gender" varchar not null, "academic_year_id" integer, "academic_class_id" integer, "father_name" varchar, "mother_name" varchar, "contact_number" varchar not null, "previous_school" varchar, "status" varchar not null default 'Pending', "application_date" date not null, "created_at" datetime, "updated_at" datetime, foreign key("academic_year_id") references "academic_years"("id") on delete set null, foreign key("academic_class_id") references "academic_classes"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "admission_documents" ("id" integer not null primary key autoincrement, "admission_application_id" integer not null, "title" varchar not null, "document_path" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("admission_application_id") references "admission_applications"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "periods" ("id" integer not null primary key autoincrement, "name" varchar not null, "start_time" time not null, "end_time" time not null, "sort_order" integer not null default '0', "is_break" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "timetable_entries" ("id" integer not null primary key autoincrement, "academic_year_id" integer not null, "academic_class_id" integer not null, "section_id" integer, "period_id" integer not null, "day_of_week" varchar not null, "subject_id" integer not null, "staff_id" integer, "room" varchar, "custom_start_time" time, "custom_end_time" time, "created_at" datetime, "updated_at" datetime, foreign key("academic_year_id") references "academic_years"("id") on delete cascade, foreign key("academic_class_id") references "academic_classes"("id") on delete cascade, foreign key("section_id") references "sections"("id") on delete set null, foreign key("period_id") references "periods"("id") on delete cascade, foreign key("subject_id") references "subjects"("id") on delete cascade, foreign key("staff_id") references "staff"("id") on delete set null);
CREATE UNIQUE INDEX "unique_class_period_day" on "timetable_entries" ("academic_class_id", "section_id", "period_id", "day_of_week");
CREATE TABLE IF NOT EXISTS "fee_types" ("id" integer not null primary key autoincrement, "name" varchar not null, "description" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "fee_structures" ("id" integer not null primary key autoincrement, "academic_year_id" integer not null, "academic_class_id" integer, "fee_type_id" integer not null, "billing_cycle" varchar not null default 'Monthly', "amount" numeric not null, "created_at" datetime, "updated_at" datetime, foreign key("academic_year_id") references "academic_years"("id") on delete cascade, foreign key("academic_class_id") references "academic_classes"("id") on delete cascade, foreign key("fee_type_id") references "fee_types"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "fee_discounts" ("id" integer not null primary key autoincrement, "name" varchar not null, "type" varchar check ("type" in ('percentage', 'fixed')) not null, "amount" numeric not null, "description" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "fee_invoices" ("id" integer not null primary key autoincrement, "student_id" integer not null, "academic_year_id" integer not null, "title" varchar not null, "subtotal" numeric not null default '0', "discount_amount" numeric not null default '0', "fine_amount" numeric not null default '0', "total_amount" numeric not null default '0', "paid_amount" numeric not null default '0', "status" varchar check ("status" in ('Unpaid', 'Partial', 'Paid')) not null default 'Unpaid', "due_date" date, "created_at" datetime, "updated_at" datetime, "journal_entry_id" integer, "previous_due" numeric not null default '0', "remarks" text, "nepali_month" varchar, foreign key("student_id") references "students"("id") on delete cascade, foreign key("academic_year_id") references "academic_years"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "fee_invoice_items" ("id" integer not null primary key autoincrement, "fee_invoice_id" integer not null, "fee_type_id" integer not null, "amount" numeric not null, "created_at" datetime, "updated_at" datetime, foreign key("fee_invoice_id") references "fee_invoices"("id") on delete cascade, foreign key("fee_type_id") references "fee_types"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "fee_payments" ("id" integer not null primary key autoincrement, "fee_invoice_id" integer not null, "payment_method" varchar not null, "amount" numeric not null, "payment_date" date not null, "reference_number" varchar, "receipt_number" varchar, "notes" text, "created_at" datetime, "updated_at" datetime, "journal_entry_id" integer, "account_id" integer, foreign key("fee_invoice_id") references "fee_invoices"("id") on delete cascade);
CREATE UNIQUE INDEX "fee_payments_receipt_number_unique" on "fee_payments" ("receipt_number");
CREATE TABLE IF NOT EXISTS "account_groups" ("id" integer not null primary key autoincrement, "name" varchar not null, "type" varchar not null, "description" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "accounts" ("id" integer not null primary key autoincrement, "account_group_id" integer not null, "name" varchar not null, "code" varchar, "description" text, "is_default" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("account_group_id") references "account_groups"("id") on delete cascade);
CREATE UNIQUE INDEX "accounts_code_unique" on "accounts" ("code");
CREATE TABLE IF NOT EXISTS "journal_entries" ("id" integer not null primary key autoincrement, "entry_date" date not null, "reference" varchar, "description" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "journal_entry_items" ("id" integer not null primary key autoincrement, "journal_entry_id" integer not null, "account_id" integer not null, "type" varchar check ("type" in ('debit', 'credit')) not null, "amount" numeric not null, "created_at" datetime, "updated_at" datetime, foreign key("journal_entry_id") references "journal_entries"("id") on delete cascade, foreign key("account_id") references "accounts"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "exam_schedules" ("id" integer not null primary key autoincrement, "exam_id" integer not null, "academic_class_id" integer not null, "subject_id" integer not null, "exam_date" date, "start_time" time, "end_time" time, "theory_full_marks" numeric not null default '0', "theory_pass_marks" numeric not null default '0', "practical_full_marks" numeric not null default '0', "practical_pass_marks" numeric not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("exam_id") references "exams"("id") on delete cascade, foreign key("academic_class_id") references "academic_classes"("id") on delete cascade, foreign key("subject_id") references "subjects"("id") on delete cascade);
CREATE UNIQUE INDEX "exam_schedule_unique" on "exam_schedules" ("exam_id", "academic_class_id", "subject_id");
CREATE TABLE IF NOT EXISTS "exam_marks" ("id" integer not null primary key autoincrement, "exam_id" integer not null, "student_id" integer not null, "subject_id" integer not null, "theory_marks" numeric, "practical_marks" numeric, "is_absent" tinyint(1) not null default '0', "remarks" varchar, "created_at" datetime, "updated_at" datetime, foreign key("exam_id") references "exams"("id") on delete cascade, foreign key("student_id") references "students"("id") on delete cascade, foreign key("subject_id") references "subjects"("id") on delete cascade);
CREATE UNIQUE INDEX "exam_marks_unique" on "exam_marks" ("exam_id", "student_id", "subject_id");
CREATE TABLE IF NOT EXISTS "grading_rules" ("id" integer not null primary key autoincrement, "grade_name" varchar not null, "min_percent" numeric not null, "max_percent" numeric not null, "grade_point" numeric not null, "remarks" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "academic_class_subject" ("id" integer not null primary key autoincrement, "academic_class_id" integer not null, "subject_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("academic_class_id") references "academic_classes"("id") on delete cascade, foreign key("subject_id") references "subjects"("id") on delete cascade);
CREATE UNIQUE INDEX "academic_class_subject_academic_class_id_subject_id_unique" on "academic_class_subject" ("academic_class_id", "subject_id");
CREATE TABLE IF NOT EXISTS "homework" ("id" integer not null primary key autoincrement, "title" varchar not null, "description" text, "class_id" integer not null, "section_id" integer not null, "subject_id" integer not null, "due_date" date not null, "file_path" varchar, "status" varchar not null default 'Active', "created_at" datetime, "updated_at" datetime, "total_marks" numeric default '100', foreign key("class_id") references "academic_classes"("id") on delete cascade, foreign key("section_id") references "sections"("id") on delete cascade, foreign key("subject_id") references "subjects"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "study_materials" ("id" integer not null primary key autoincrement, "title" varchar not null, "description" text, "class_id" integer not null, "subject_id" integer not null, "file_path" varchar, "status" varchar not null default 'Active', "created_at" datetime, "updated_at" datetime, foreign key("class_id") references "academic_classes"("id") on delete cascade, foreign key("subject_id") references "subjects"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "student_kudos" ("id" integer not null primary key autoincrement, "student_id" integer not null, "sender_id" integer, "icon" varchar not null default '⭐', "message" text not null, "is_read" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("student_id") references "students"("id") on delete cascade, foreign key("sender_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "academic_class_section" ("id" integer not null primary key autoincrement, "academic_class_id" integer not null, "section_id" integer not null, foreign key("academic_class_id") references "academic_classes"("id") on delete cascade, foreign key("section_id") references "sections"("id") on delete cascade);
CREATE UNIQUE INDEX "academic_class_section_academic_class_id_section_id_unique" on "academic_class_section" ("academic_class_id", "section_id");
CREATE TABLE IF NOT EXISTS "sections" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name VARCHAR(255) NOT NULL,
                academic_class_id INTEGER NULL REFERENCES academic_classes(id) ON DELETE SET NULL,
                capacity INTEGER NULL,
                created_at DATETIME NULL,
                updated_at DATETIME NULL
            );
CREATE TABLE IF NOT EXISTS "communications" ("id" integer not null primary key autoincrement, "type" varchar not null, "subject" varchar, "message" text not null, "recipient_id" integer, "recipient_type" varchar, "status" varchar not null default 'pending', "error_message" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "communication_templates" ("id" integer not null primary key autoincrement, "name" varchar not null, "type" varchar not null, "subject" varchar, "body" text not null, "variables" text, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "communication_configs" ("id" integer not null primary key autoincrement, "channel" varchar not null, "driver" varchar not null, "config" text, "is_active" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "communication_configs_channel_unique" on "communication_configs" ("channel");
