CREATE UNIQUE INDEX "homework_submissions_homework_id_student_id_unique" on "homework_submissions" ("homework_id", "student_id");
CREATE TABLE IF NOT EXISTS "certificates" ("id" integer not null primary key autoincrement, "certificate_no" varchar not null, "student_id" integer not null, "type" varchar not null, "title" varchar not null, "issue_date" date not null, "metadata" text, "qr_token" varchar not null, "status" varchar not null default 'issued', "revocation_reason" text, "issued_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("student_id") references "students"("id") on delete cascade, foreign key("issued_by") references "users"("id") on delete set null);
