CREATE TABLE IF NOT EXISTS "library_book_copies" ("id" integer not null primary key autoincrement, "library_book_id" integer not null, "barcode" varchar not null, "status" varchar not null default 'available', "condition" varchar, "created_at" datetime, "updated_at" datetime, foreign key("library_book_id") references "library_books"("id") on delete cascade);
